+int main(int argc, char *argv[]) {
+    parse_args(argc, argv);
+    
+    if (force_term) {
+        setenv("TERM", "linux", 1);
+    }
+    
+    if (!init_tty()) {
+        return 1;
+    }
+    
+    run();
+    
+    restore_tty();
+    return 0;
+}
